		Size = UDim2.fromOffset(18, 18),
		BackgroundColor3 = THEME.Text,
		BorderSizePixel = 0,
		Parent = button,
	}, { corner(9) })
	local control = { Value = default == true }
	function control:SetValue(value, silent)
