function Tab:AddModule(options)
	if type(options) == "string" then options = { Name = options } end
	options = options or {}
	local module = setmetatable({
		Window = self.Window,
		Tab = self,
		Name = options.Name or "Module",
		SearchText = (self.Window:Text(options.Name or "Module") .. " " .. self.Window:Text(options.Description or "")):lower(),
		HeaderHeight = options.HeaderHeight or 56,
		Expanded = options.Expanded == true or options.Collapsible == false,
		Collapsible = options.Collapsible ~= false,
		Enabled = false,
	}, Module)
	module.Card = create("Frame", {
		Name = module.Name,
		Size = UDim2.new(1, -CARD_HORIZONTAL_GUTTER, 0, module.HeaderHeight),
		BackgroundColor3 = THEME.PanelRaised,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Active = true,
		LayoutOrder = #self.Modules + 1,
		Parent = self.Scroll,
	}, { corner(13), stroke(THEME.Border, 0.25) })
	module.Accent = create("Frame", {
		Position = UDim2.fromOffset(4, 10),
		Size = UDim2.fromOffset(3, math.max(20, module.HeaderHeight - 20)),
		BackgroundColor3 = options.Accent and THEME.Accent or THEME.Border,
		BorderSizePixel = 0,
		ZIndex = 3,
		Parent = module.Card,
	}, { corner(3) })
	create("TextLabel", {
		Position = UDim2.fromOffset(22, 9),
		Size = UDim2.new(1, -(options.RightInset or (options.Toggleable and 148 or 58)), 0, 22),
		BackgroundTransparency = 1,
		Text = module.Name,
		TextColor3 = THEME.Text,
		TextXAlignment = Enum.TextXAlignment.Left,
		Font = Enum.Font.BuilderSansBold,
		TextSize = options.TitleSize or 16,
		Parent = module.Card,
	})
	module.Status = create("TextLabel", {
		Position = UDim2.fromOffset(22, 30),
		Size = UDim2.new(1, -(options.RightInset or (options.Toggleable and 148 or 64)), 0, 20),
		BackgroundTransparency = 1,
		Text = options.Description or options.Status or "Ready",
		TextColor3 = THEME.Muted,
		TextTruncate = Enum.TextTruncate.AtEnd,
		TextXAlignment = Enum.TextXAlignment.Left,
		Font = Enum.Font.BuilderSansMedium,
		TextSize = 12,
		Parent = module.Card,
	})
	module.Chevron = chevron(module.Card, UDim2.new(1, options.Toggleable and -100 or -36, 0, 25))
	module.Chevron.Visible = module.Collapsible
	local headerButton = create("TextButton", {
		Size = UDim2.new(1, options.Toggleable and -78 or 0, 0, module.HeaderHeight),
		AutoButtonColor = false,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Text = "",
		ZIndex = 2,
		Parent = module.Card,
	})
	module.Body = create("Frame", {
		Position = UDim2.fromOffset(CARD_BODY_INSET, module.HeaderHeight),
		Size = UDim2.new(1, -(CARD_BODY_INSET * 2), 0, 0),
		BackgroundTransparency = 1,
		Parent = module.Card,
	})
	module.BodyLayout = create("UIListLayout", {
		Padding = UDim.new(0, 10),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = module.Body,
	})
	self.Window:_connect(module.BodyLayout:GetPropertyChangedSignal("AbsoluteContentSize"), function()
		module:_refreshHeight()
	end)
	if module.Collapsible then
		self.Window:_connect(headerButton.Activated, function()
			module:SetExpanded(not module.Expanded)
		end)
		self.Window:_connect(headerButton.MouseEnter, function()
			self.Window:_tween(module.Card, 0.14, { BackgroundColor3 = THEME.Surface })
		end)
		self.Window:_connect(headerButton.MouseLeave, function()
			self.Window:_tween(module.Card, 0.14, { BackgroundColor3 = THEME.PanelRaised })
		end)
	end
	if options.Toggleable then
		module.Toggle = module:AddToggle("", options.Default == true, options.Callback)
		local toggleRow = module.Toggle
		for _, child in ipairs(module.Body:GetChildren()) do
			if child:IsA("Frame") then
				child.Visible = false
				child.Size = UDim2.new(1, 0, 0, 0)
				break
			end
		end
		local toggleButton = create("TextButton", {
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -22, 0, 18),
			Size = UDim2.fromOffset(48, 26),
			AutoButtonColor = false,
			BackgroundColor3 = THEME.Surface,
			BorderSizePixel = 0,
			Text = "",
			ZIndex = 5,
			Parent = module.Card,
		}, { corner(12) })
		local knob = create("Frame", {
			Position = UDim2.fromOffset(3, 3),
			Size = UDim2.fromOffset(20, 20),
			BackgroundColor3 = THEME.Text,
			BorderSizePixel = 0,
			ZIndex = 6,
			Parent = toggleButton,
		}, { corner(9) })
		function toggleRow:SetValue(value, silent)
			self.Value = value == true
			self.Module.Window:_tween(toggleButton, 0.14, {
				BackgroundColor3 = self.Value and THEME.Accent or THEME.Surface,
			})
			self.Module.Window:_tween(knob, 0.14, {
				Position = self.Value and UDim2.fromOffset(25, 3) or UDim2.fromOffset(3, 3),
			})
			self.Module:SetEnabled(self.Value)
			if not silent then safeCall(self.Module.Window, options.Callback, self.Value) end
		end
		local hitTarget = create("TextButton", {
			AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -14, 0, 9),
			Size = UDim2.fromOffset(64, 44), Text = "", BackgroundTransparency = 1,
			ZIndex = 7, Parent = module.Card,
		})
		self.Window:_connect(hitTarget.Activated, function()
			toggleRow:SetValue(not toggleRow.Value)
		end)
		toggleRow:SetValue(options.Default == true, true)
	end
	if options.Feature then options.Feature:BindControl(module) end

	module:SetExpanded(module.Expanded)
	table.insert(self.Modules, module)
	self.Window:_refreshSearch()
	return module
end

function Module:AddKeybind(options)
	options = options or {}
	self:_index(options.Name or "Keybind")
	local row = self:_row(60)
	create("TextLabel", {
		Position = UDim2.fromOffset(16, 0), Size = UDim2.new(1, -172, 1, 0),
		Text = options.Name or "Toggle key", TextColor3 = THEME.Text,
		TextSize = 13, Font = Enum.Font.BuilderSansBold, TextXAlignment = Enum.TextXAlignment.Left,
		BackgroundTransparency = 1, Parent = row,
	})
	local button = create("TextButton", {
		Position = UDim2.new(1, -148, 0, 8), Size = UDim2.fromOffset(136, 44),
		BackgroundColor3 = THEME.PanelRaised, BorderSizePixel = 0,
		TextColor3 = THEME.Text, TextSize = 13, Font = Enum.Font.BuilderSansBold,
		AutoButtonColor = false, Parent = row,
	}, { corner(9), stroke(THEME.Border, 0.3) })
	local binding = {
		Window = self.Window,
		Button = button,
		Name = options.Name or "Keybind",
		Get = options.Get,
		Set = options.Set,
		OnPressed = options.OnPressed,
		AllowClear = options.AllowClear ~= false,
		IsVisibility = options.IsVisibility == true,
	}
	function binding:Refresh()
		local key = self.Get()
		self.Button.Text = key == Enum.KeyCode.Unknown and "None" or key.Name
		self.Button.TextColor3 = THEME.Text
	end
	self.Window:_hover(button, THEME.PanelRaised, THEME.SurfaceHover)
	self.Window:_connect(button.Activated, function()
		if self.Window._rebinding then self.Window._rebinding:Refresh() end
		self.Window._rebinding = binding
		button.Text = "Press a key..."
		button.TextColor3 = THEME.Accent
	end)
	table.insert(self.Window.Keybinds, binding)
	binding:Refresh()
	return binding
end

-- Compatibility helper; new game UIs place keybinds in their owning module.
function Tab:AddKeybind(options)
	return self:AddModule({ Name = options.Name or "Shortcut", Expanded = true }):AddKeybind(options)
end

function Window:_keyInUse(key, except)
	for _, binding in ipairs(self.Keybinds) do
		if binding ~= except and binding.Get() == key then return binding.Name end
	end
	return nil
end

function Window:_handleKeyboard(input, processed)
	if self.InputEnabled == false or self._destroyed then return end
	if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
	if self._rebinding then
		local binding = self._rebinding
		local key = input.KeyCode
		if key == Enum.KeyCode.Escape then
			binding:Refresh()
		elseif (key == Enum.KeyCode.Backspace or key == Enum.KeyCode.Delete) and binding.AllowClear then
			binding.Set(Enum.KeyCode.Unknown)
			binding:Refresh()
		elseif self.ReservedKeys[key] then
			binding:Refresh()
			self:Notify({ Title = "Reserved key", Text = key.Name .. " is used for movement.", Type = "Error" })
		else
			local conflict = self:_keyInUse(key, binding)
			if conflict then
				binding:Refresh()
				self:Notify({ Title = "Key already assigned", Text = key.Name .. " is bound to " .. conflict .. ".", Type = "Error" })
			else
				binding.Set(key)
				binding:Refresh()
			end
		end
		self._rebinding = nil
		return
	end
	if self._dropdown and input.KeyCode == Enum.KeyCode.Escape then self:CloseDropdown(); return end
	if input.KeyCode == Enum.KeyCode.K and (UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)
		or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)) and not processed then
		self:SetVisible(true)
		if self.ActiveTab and self.ActiveTab.SearchEnabled ~= false then self.Search:CaptureFocus() end
		return
	end
	if UserInputService:GetFocusedTextBox() == self.Search and input.KeyCode == Enum.KeyCode.Escape then
		self:SetSearch(""); self.Search:ReleaseFocus(); return
	end
	if self._dropdown or processed or UserInputService:GetFocusedTextBox() then return end
	for _, binding in ipairs(self.Keybinds) do
		local key = binding.Get()
		if key ~= Enum.KeyCode.Unknown and input.KeyCode == key then
			safeCall(self, binding.OnPressed)
			break
		end
	end
end

function Window:SetMonitor(key, text)
	local nextText = text ~= nil and tostring(text) or nil
	local monitor = self.Monitors[key]
	local wasVisible = monitor and monitor.Frame.Visible
	if not monitor then
		self._monitorCount += 1
		local frame = create("Frame", {
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -22, 0, 22 + ((self._monitorCount - 1) * 74)),
			Size = UDim2.fromOffset(self.MonitorWidth, 64),
			BackgroundColor3 = THEME.PanelRaised,
			BackgroundTransparency = 0.04,
			BorderSizePixel = 0,
			ClipsDescendants = true,
			Parent = self.OverlayGui,
		}, { corner(10), stroke(THEME.Border, 0.25) })
		create("Frame", {
			Position = UDim2.fromOffset(0, 10),
			Size = UDim2.fromOffset(4, 44),
			BackgroundColor3 = THEME.Accent,
			BorderSizePixel = 0,
			Parent = frame,
		}, { corner(3) })
		local label = create("TextLabel", {
			Position = UDim2.fromOffset(18, 8),
			Size = UDim2.new(1, -34, 1, -16),
			BackgroundTransparency = 1,
			TextColor3 = THEME.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Center,
			TextWrapped = true,
			Font = Enum.Font.BuilderSansBold,
			TextSize = 13,
			Parent = frame,
		})
		self:_makeDraggable(frame, frame)
		monitor = { Frame = frame, Label = label, Order = self._monitorCount }
		self.Monitors[key] = monitor
	end
	if monitor.Text == nextText and monitor.Frame.Visible == (nextText ~= nil) then
		return monitor
	end
	monitor.Text = nextText
	monitor.Label.Text = nextText or ""
	monitor.Frame.Visible = nextText ~= nil
	if not wasVisible and nextText ~= nil then self:_layoutMonitors() end
	self:_applyTextScale()
	return monitor
end

function Window:HideMonitor(key)
	if self.Monitors[key] then
		self.Monitors[key].Frame.Visible = false
		self:_layoutMonitors()
	end
end

function Window:_layoutNotifications()
	local size = self.OverlayGui.AbsoluteSize
	local maxVisible = math.max(1, math.min(3, math.floor((size.Y - 32) / 108)))
	for index = #self.Notifications, 1, -1 do
		if not self.Notifications[index].Parent then table.remove(self.Notifications, index) end
	end
	while #self.Notifications > maxVisible do table.remove(self.Notifications, 1):Destroy() end
	for index, frame in ipairs(self.Notifications) do
		frame.Size = UDim2.fromOffset(math.min(380, math.max(120, size.X - 32)), 96)
		frame.Position = UDim2.new(1, -16, 1, -16 - (#self.Notifications - index) * 108)
	end
end

function Window:Notify(options)
	if self._destroyed or self.NotificationsEnabled == false then return nil end
	self:PlaySound("Notify")
	if type(options) == "string" then options = { Text = options } end
	options = options or {}
	local duration = math.clamp(tonumber(options.Duration) or 4, 1, 30)
	local tint = options.Type == "Error" and THEME.Danger or options.Type == "Success" and THEME.Success or THEME.Accent
	local frame = create("CanvasGroup", {
		Name = "Notification", AnchorPoint = Vector2.new(1, 1), Size = UDim2.fromOffset(380, 96),
		BackgroundColor3 = THEME.PanelRaised, BorderSizePixel = 0, GroupTransparency = 1,
		Parent = self.NotificationGui,
	}, { corner(12), stroke(tint, 0.6) })
	create("Frame", { Position = UDim2.fromOffset(0, 16), Size = UDim2.new(0, 3, 1, -32),
		BackgroundColor3 = tint, BorderSizePixel = 0, Parent = frame }, { corner(2) })
	create("TextLabel", { Position = UDim2.fromOffset(16, 12), Size = UDim2.new(1, -66, 0, 22),
		Text = options.Title or "FrostScripts", TextColor3 = tint, BackgroundTransparency = 1,
		TextXAlignment = Enum.TextXAlignment.Left, TextSize = 14, Font = Enum.Font.BuilderSansBold, Parent = frame })
	create("TextLabel", { Position = UDim2.fromOffset(16, 38), Size = UDim2.new(1, -32, 0, 44),
		Text = options.Text or "", TextColor3 = THEME.Text, BackgroundTransparency = 1, TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
		TextSize = 12, Font = Enum.Font.BuilderSansMedium, Parent = frame })
	local close = create("TextButton", { Position = UDim2.new(1, -44, 0, 0), Size = UDim2.fromOffset(44, 44),
		Text = "×", TextColor3 = THEME.Muted, TextSize = 20, Font = Enum.Font.BuilderSans,
		BackgroundTransparency = 1, Parent = frame })
	local progress = create("Frame", { Position = UDim2.new(0, 0, 1, -2), Size = UDim2.new(1, 0, 0, 2),
		BackgroundColor3 = tint, BorderSizePixel = 0, Parent = frame })
	local closeConnection
	closeConnection = close.Activated:Connect(function()
		closeConnection:Disconnect()
		frame:Destroy()
		if not self._destroyed then self:_layoutNotifications() end
	end)
	table.insert(self.Notifications, frame)
	self:_layoutNotifications()
	self:_queueTextScale()
	self:_tween(frame, 0.18, { GroupTransparency = 0 })
	if self.Animations then self:_tween(progress, duration, { Size = UDim2.new(0, 0, 0, 2) }, Enum.EasingStyle.Linear) end
	task.delay(duration, function()
		closeConnection:Disconnect()
		if self._destroyed or not frame.Parent then return end
		self:_tween(frame, 0.14, { GroupTransparency = 1 })
		task.delay(self.Animations and 0.15 or 0, function()
			frame:Destroy()
			if not self._destroyed then self:_layoutNotifications() end
		end)
	end)
	return frame
end


function Window:AddWorldMarker(instances, object, options)
	options = options or {}
	instances = instances or {}
	local color = options.Color or THEME.Accent
	local adornment = object:IsA("Model") and object or object:FindFirstAncestorWhichIsA("Model") or object
	local part = options.Adornee
	if not (typeof(part) == "Instance" and part:IsA("BasePart")) then
		part = adornment:IsA("BasePart") and adornment or adornment:FindFirstChildWhichIsA("BasePart", true)
	end
	if not part then return end
	local highlight
	if options.Highlight ~= false then
		highlight = Instance.new("Highlight")
		highlight.Name = "FrostScriptsMarker"
		highlight.Adornee = adornment
		highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		highlight.FillColor = color
		highlight.FillTransparency = 0.8
		highlight.OutlineColor = color
		highlight.OutlineTransparency = 0.18
		highlight.Parent = adornment
		instances[highlight] = true
	end
	local scale = math.clamp(tonumber(options.Scale) or 1, 0.1, 1.8)
	local baseWidth = math.max(80, tonumber(options.Width) or 220)
	local baseHeight = math.max(28, tonumber(options.Height) or 52)
	local titleTextSize = math.max(8, tonumber(options.TitleTextSize) or 14)
	local detailTextSize = math.max(8, tonumber(options.DetailTextSize) or 12)
	local compact = options.Compact == true
	local horizontalPadding = compact and 10 or 14
	local titleY = compact and 3 or 5
	local detailY = compact and math.floor(baseHeight * 0.52) or 26
	local offset = typeof(options.Offset) == "Vector3" and options.Offset or Vector3.new(0, 2.5, 0)
	local sizeOffset = typeof(options.SizeOffset) == "Vector2" and options.SizeOffset or Vector2.zero
	local billboard = create("BillboardGui", {
		Name = "FrostScriptsLabel",
		Adornee = part,
		AlwaysOnTop = true,
		MaxDistance = tonumber(options.MaxDistance) or 750,
		Size = UDim2.fromOffset(baseWidth * scale, baseHeight * scale),
		StudsOffsetWorldSpace = offset,
		SizeOffset = sizeOffset,
		Parent = self.OverlayGui,
	})
	local panelStroke = stroke(color, 0.22)
	local panel = create("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = THEME.Background,
		BackgroundTransparency = 0.12,
		BorderSizePixel = 0,
		Parent = billboard,
	}, { corner(9), panelStroke })
	local titleLabel = create("TextLabel", {
		Position = UDim2.fromOffset(horizontalPadding * scale, titleY * scale),
		Size = UDim2.new(1, -horizontalPadding * 2 * scale, 0, (compact and 17 or 21) * scale),
		BackgroundTransparency = 1,
		Text = options.Title or "Marker",
		TextColor3 = THEME.Text,
		TextXAlignment = Enum.TextXAlignment.Left,
		Font = Enum.Font.BuilderSansBold,
		TextSize = titleTextSize * scale,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = panel,
	})
	local detailLabel = create("TextLabel", {
		Position = UDim2.fromOffset(horizontalPadding * scale, detailY * scale),
		Size = UDim2.new(1, -horizontalPadding * 2 * scale, 0, (compact and 14 or 18) * scale),
		BackgroundTransparency = 1,
		Text = options.Detail or "Marker",
		TextColor3 = color,
		TextXAlignment = Enum.TextXAlignment.Left,
		Font = Enum.Font.BuilderSansMedium,
		TextSize = detailTextSize * scale,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = panel,
	})
	instances[billboard] = true
	local marker = {
		Billboard = billboard,
		Highlight = highlight,
	}
	local function applyGeometry()
		billboard.Size = UDim2.fromOffset(baseWidth * scale, baseHeight * scale)
		titleLabel.Position = UDim2.fromOffset(horizontalPadding * scale, titleY * scale)
		titleLabel.Size = UDim2.new(1, -horizontalPadding * 2 * scale, 0, (compact and 17 or 21) * scale)
		titleLabel.TextSize = titleTextSize * scale
		detailLabel.Position = UDim2.fromOffset(horizontalPadding * scale, detailY * scale)
		detailLabel.Size = UDim2.new(1, -horizontalPadding * 2 * scale, 0, (compact and 14 or 18) * scale)
		detailLabel.TextSize = detailTextSize * scale
	end
	function marker:Update(nextOptions)
		nextOptions = nextOptions or {}
		local nextColor = nextOptions.Color or color
		local nextScale = math.clamp(tonumber(nextOptions.Scale) or scale, 0.1, 1.8)
		titleLabel.Text = nextOptions.Title or titleLabel.Text
		detailLabel.Text = nextOptions.Detail or detailLabel.Text
		detailLabel.TextColor3 = nextColor
		panelStroke.Color = nextColor
		billboard.MaxDistance = tonumber(nextOptions.MaxDistance) or billboard.MaxDistance
		if typeof(nextOptions.Adornee) == "Instance" and nextOptions.Adornee:IsA("BasePart") then
			billboard.Adornee = nextOptions.Adornee
		end
		if typeof(nextOptions.Offset) == "Vector3" then
			billboard.StudsOffsetWorldSpace = nextOptions.Offset
		end
		if typeof(nextOptions.SizeOffset) == "Vector2" then
			billboard.SizeOffset = nextOptions.SizeOffset
		end
		if nextScale ~= scale then
			scale = nextScale
			applyGeometry()
		end
		if highlight then
			highlight.FillColor = nextColor
			highlight.OutlineColor = nextColor
		end
		color = nextColor
	end
	function marker:Destroy()
		if highlight then
			instances[highlight] = nil
			if highlight.Parent then highlight:Destroy() end
		end
		instances[billboard] = nil
		if billboard.Parent then billboard:Destroy() end
	end
	return marker
end

function Window:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	if self._ambientConnection then self._ambientConnection:Disconnect(); self._ambientConnection = nil end
	self:CloseDropdown()
	for _, connection in ipairs(self._connections) do connection:Disconnect() end
	table.clear(self._connections)
	for _, running in pairs(self._tweens) do
		for _, animation in pairs(running) do animation:Cancel() end
	end
	table.clear(self._tweens)
	if self.Gui then self.Gui:Destroy() end
	if self.OverlayGui then self.OverlayGui:Destroy() end
	if self.NotificationGui then self.NotificationGui:Destroy() end
end

function Window:_applyTheme()
	for _, running in pairs(self._tweens) do
		for property, animation in pairs(running) do
			if property:find("Color") then animation:Cancel(); running[property] = nil end
		end
	end
	local function apply(root)
		if not root then return end
		local objects = root:GetDescendants()
		table.insert(objects, root)
		for _, object in ipairs(objects) do
			for attribute, themeKey in pairs(object:GetAttributes()) do
				local property = attribute:match("^FrostTheme_(.+)$")
				if property and THEME[themeKey] then
					pcall(function()
						object[property] = THEME[themeKey]
					end)
				end
			end
		end
	end
	apply(self.Gui)
	apply(self.OverlayGui)
	apply(self.NotificationGui)
	if self.ActiveTab then
		for _, item in ipairs(self.Tabs) do
			local selected = item == self.ActiveTab
			item.Button.BackgroundColor3 = selected and THEME.AccentSoft or THEME.Panel
			item.Label.TextColor3 = selected and THEME.Text or THEME.Muted
			item.IconLabel.TextColor3 = selected and THEME.Accent or THEME.Muted
			item.IconLabel.BackgroundColor3 = selected and THEME.AccentSoft or THEME.Surface
			item.Indicator.BackgroundColor3 = THEME.Accent
			item.Indicator.BackgroundTransparency = selected and 0 or 1
		end
	end
end

function Window:SetTheme(themeName)
	local source = THEMES[themeName]
	if not source then return false end
	self.ThemeName = themeName
	self:_remember("ThemeName", themeName)
	self:_remember("CustomAccent", nil)
	self:_remember("CustomSuccess", nil)
	for key, value in pairs(source) do
		THEME[key] = value
	end
	self:_applyTheme()
	for _, gallery in ipairs(self.ThemeGalleries or {}) do gallery:Refresh() end
	return true
end

function Window:SetThemeColor(key, color)
	if not THEME[key] or typeof(color) ~= "Color3" then return false end
	THEME[key] = color
	if key == "Accent" or key == "Success" then self:_remember("Custom" .. key, color) end
	self.CustomTheme = true
	self:_applyTheme()
	return true
end

function Window:GetThemeColor(key)
	return THEME[key]
end

function Window:GetThemeNames()
	return { "Black", "Graphite", "Midnight", "Frost", "Amethyst", "Forest", "Ember", "Rose", "Neon", "Hayfield" }
end

function Module:AddColorPicker(name, default, callback)
	self:_index(name)
	local value = typeof(default) == "Color3" and default or THEME.Accent
	local preview = self:_row(54)
	create("TextLabel", {
		Position = UDim2.fromOffset(16, 0),
		Size = UDim2.new(1, -96, 1, 0),
		BackgroundTransparency = 1,
		Text = name,
		TextColor3 = THEME.Text,
		TextXAlignment = Enum.TextXAlignment.Left,
		Font = Enum.Font.BuilderSansBold,
		TextSize = 14,
		Parent = preview,
	})
	local swatch = create("Frame", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -18, 0.5, 0),
		Size = UDim2.fromOffset(52, 30),
		BackgroundColor3 = value,
		BorderSizePixel = 0,
		Parent = preview,
	}, { corner(8), stroke(THEME.Border, 0.35) })
	local control = { Module = self, Value = value }
	local channels = {
		{ "R", function(color) return math.floor(color.R * 255 + 0.5) end },
		{ "G", function(color) return math.floor(color.G * 255 + 0.5) end },
		{ "B", function(color) return math.floor(color.B * 255 + 0.5) end },
	}
	local values = {
		R = channels[1][2](value),
		G = channels[2][2](value),
		B = channels[3][2](value),
	}
	local function refresh(silent)
		control.Value = Color3.fromRGB(values.R, values.G, values.B)
		swatch.BackgroundColor3 = control.Value
		if not silent then safeCall(control.Module.Window, callback, control.Value) end
	end
	local sliders = {}
	for _, channel in ipairs(channels) do
		sliders[channel[1]] = self:AddSlider(name .. " " .. channel[1], 0, 255, values[channel[1]], function(nextValue)
			values[channel[1]] = nextValue
			refresh(false)
		end, { Step = 1 })
	end
	function control:SetValue(color, silent)
		if typeof(color) ~= "Color3" then return end
		values.R = math.floor(color.R * 255 + 0.5)
		values.G = math.floor(color.G * 255 + 0.5)
		values.B = math.floor(color.B * 255 + 0.5)
		for channel, slider in pairs(sliders) do slider:SetValue(values[channel], true) end
		refresh(silent)
	end
	return control
end

-- Purpose-built solid navigation badges. They are drawn with native Roblox Frames,
-- so no SVG paths, font glyphs, or third-party image assets are involved.
local function badgePiece(parent, name, position, size, transparency, rotation)
	return create("Frame", {
		Name = name,
		Position = position,
		Size = size,
		Rotation = rotation or 0,
		BackgroundTransparency = transparency or 0,
		BorderSizePixel = 0,
		Parent = parent,
	}, { corner(math.max(2, math.floor(math.min(size.X.Offset, size.Y.Offset) / 3))) })
end

local function makeHome(root)
	badgePiece(root, "Roof", UDim2.fromOffset(6, 2), UDim2.fromOffset(9, 9), 0.2, 45)
	badgePiece(root, "HouseBody", UDim2.fromOffset(4, 8), UDim2.fromOffset(13, 10), 0.36)
	badgePiece(root, "Door", UDim2.fromOffset(10, 12), UDim2.fromOffset(4, 6), 0.02)
end

local function makeLibrary(root)
	badgePiece(root, "ScriptPage", UDim2.fromOffset(3, 1), UDim2.fromOffset(14, 18), 0.5)
	badgePiece(root, "ScriptBinding", UDim2.fromOffset(3, 1), UDim2.fromOffset(4, 18), 0.04)
	badgePiece(root, "ScriptLine", UDim2.fromOffset(9, 5), UDim2.fromOffset(6, 2), 0.08)
	badgePiece(root, "ScriptLine", UDim2.fromOffset(9, 9), UDim2.fromOffset(5, 2), 0.22)
	badgePiece(root, "ScriptLine", UDim2.fromOffset(9, 13), UDim2.fromOffset(7, 2), 0.38)
end

local function makeSliders(root)
	for index, x in ipairs({ 11, 6, 13 }) do
		local y = 3 + (index - 1) * 7
		badgePiece(root, "Track", UDim2.fromOffset(2, y + 2), UDim2.fromOffset(16, 2), 0.62)
		badgePiece(root, "Knob", UDim2.fromOffset(x, y), UDim2.fromOffset(5, 5), index == 2 and 0.02 or 0.14)
	end
end

local function makeModules(root)
	badgePiece(root, "CommandPanel", UDim2.fromOffset(1, 2), UDim2.fromOffset(18, 16), 0.52)
	badgePiece(root, "CommandHeader", UDim2.fromOffset(1, 2), UDim2.fromOffset(18, 4), 0.14)
	badgePiece(root, "CommandPrompt", UDim2.fromOffset(5, 9), UDim2.fromOffset(6, 2), 0.05, 42)
	badgePiece(root, "CommandPrompt", UDim2.fromOffset(5, 12), UDim2.fromOffset(6, 2), 0.05, -42)
	badgePiece(root, "CommandLine", UDim2.fromOffset(11, 12), UDim2.fromOffset(6, 2), 0.22)
end

local function makeMark(root)
	badgePiece(root, "MarkCenter", UDim2.fromOffset(7, 7), UDim2.fromOffset(6, 6), 0.02)
	for _, point in ipairs({ Vector2.new(8, 0), Vector2.new(8, 16), Vector2.new(0, 8), Vector2.new(16, 8) }) do
		badgePiece(root, "MarkPoint", UDim2.fromOffset(point.X, point.Y), UDim2.fromOffset(4, 4), 0.34)
	end
end

local ICON_BUILDERS = {
	home = makeHome,
	library = makeLibrary,
	modules = makeModules,
	settings = makeSliders,
	controls = makeSliders,
	snowflake = makeMark,
}

function Window:_attachIcon(host, name)
	host.Text = ""
	local root = create("Frame", {
		Name = "NavigationBadge_" .. name,
		Size = UDim2.fromOffset(20, 20),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Parent = host,
	})
	local buildBadge = ICON_BUILDERS[name] or makeSliders
	buildBadge(root)

	local function tint()
		for _, piece in ipairs(root:GetDescendants()) do
			if piece:IsA("Frame") then piece.BackgroundColor3 = host.TextColor3 end
		end
	end
	self:_connect(host:GetPropertyChangedSignal("TextColor3"), tint)
	tint()
	return root
end

-- Inline palette previews, with separate hover and selected treatments.
function Window:AddThemeGallery(tab)
	local module = tab:AddModule({ Name = "Themes", Description = "Choose a palette. Your whole workspace changes together.", Expanded = true })
	local row = module:_row(348)
	row.Name, row.BackgroundTransparency = "ThemeGallery", 1
	local layout = create("UIGridLayout", { CellSize = UDim2.new(1 / 3, -8, 0, 78),
		CellPadding = UDim2.fromOffset(10, 10), SortOrder = Enum.SortOrder.LayoutOrder, Parent = row })
	local gallery = { Window = self, Module = module, Row = row, LayoutObject = layout, Tiles = {} }
	local function fixed(object)
		-- Palette previews show their own colors even when another theme is selected.
		for name in pairs(object:GetAttributes()) do
			if name:match("^FrostTheme_") then object:SetAttribute(name, nil) end
		end
		return object
	end
	for index, name in ipairs(self:GetThemeNames()) do
		local palette = THEMES[name]
		local border = stroke(THEME.Border, 0.35)
		local button = create("TextButton", { Name = name .. "Theme", Text = "", LayoutOrder = index,
			AutoButtonColor = false, BackgroundColor3 = THEME.PanelRaised, BorderSizePixel = 0, Parent = row,
		}, { corner(10), border })
		local preview = fixed(create("Frame", { Name = "PalettePreview", Position = UDim2.fromOffset(7, 7),
			Size = UDim2.new(1, -14, 0, 34), BackgroundColor3 = palette.Background, BorderSizePixel = 0, Parent = button }, { corner(6) }))
		fixed(create("Frame", { Size = UDim2.new(0.2, 0, 1, 0), BackgroundColor3 = palette.Panel,
			BorderSizePixel = 0, Parent = preview }, { corner(6) }))
		for bar, key in ipairs({ "Accent", "Surface", "Muted" }) do
			fixed(create("Frame", { Position = UDim2.new(0.28, 0, 0, 7 + (bar - 1) * 8),
				Size = UDim2.new(bar == 3 and 0.35 or 0.6, 0, 0, 3), BackgroundColor3 = palette[key],
				BorderSizePixel = 0, Parent = preview }, { corner(2) }))
		end
		local label = create("TextLabel", { Text = name, Position = UDim2.fromOffset(10, 47),
			Size = UDim2.new(1, -20, 0, 24), BackgroundTransparency = 1, TextColor3 = THEME.Text,
			Font = Enum.Font.BuilderSansMedium, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, Parent = button })
		local selected = create("Frame", { Name = "SelectedIndicator", Position = UDim2.new(1, -16, 0, 53),
			Size = UDim2.fromOffset(6, 6), BackgroundColor3 = THEME.Accent, BorderSizePixel = 0, Parent = button }, { corner(3) })
		local tile = { Name = name, Button = button, Border = border, Label = label, Selected = selected, Preview = preview }
		table.insert(gallery.Tiles, tile)
		self:_connect(button.Activated, function() self:SetTheme(name) end)
		self:_connect(button.MouseEnter, function()
			if self.ThemeName ~= name then self:_tween(button, 0.14, { BackgroundColor3 = THEME.Surface }) end
		end)
		self:_connect(button.MouseLeave, function() gallery:Refresh() end)
	end
	function gallery:Refresh()
		for _, tile in ipairs(self.Tiles) do
			local selected = self.Window.ThemeName == tile.Name
			self.Window:_tween(tile.Button, 0.14, { BackgroundColor3 = selected and THEME.AccentSoft or THEME.PanelRaised })
			self.Window:_tween(tile.Border, 0.14, { Color = selected and THEME.Accent or THEME.Border, Transparency = selected and 0 or 0.35 })
			tile.Selected.Visible = selected
		end
		self.Module:SetStatus("Current palette: " .. self.Window.ThemeName)
	end
	function gallery:Layout()
		local width = self.Window.TargetSize.X - (self.Window._compact and 72 or 216) - 80
		local columns = width >= 560 and 3 or 2
		self.LayoutObject.CellSize = UDim2.new(1 / columns, -7, 0, 78)
		self.Row.Size = UDim2.new(1, 0, 0, math.ceil(#self.Tiles / columns) * 88 - 10)
		self.Module:_refreshHeight()
	end
	self.ThemeGalleries = self.ThemeGalleries or {}
	table.insert(self.ThemeGalleries, gallery)
	gallery:Layout()
	gallery:Refresh()
	return gallery
end

-- UI-only motion, background, feedback, and preferences.
local RunService = game:GetService("RunService")

function Window:_remember(key, value)
	if self.UIState then self.UIState[key] = value end
end

function Window:PlaySound(kind)
	if self._destroyed or not self.Sounds or self.SoundVolume <= 0 then return end
	local now = os.clock()
	if now - (self._lastSound or -1) < (kind == "Hover" and 0.12 or 0.04) then return end
	self._lastSound = now
	local pitch = ({ Hover = 1.6, Click = 1.25, Open = 0.95, Notify = 1.1 })[kind] or 1.25
	pcall(function()
		self.UISound.Volume = self.SoundVolume * (kind == "Hover" and 0.35 or 1)
		self.UISound.PlaybackSpeed = pitch
		self.UISound.TimePosition = 0
		self.UISound:Play()
	end)
end

function Window:SetSounds(enabled)
	self.Sounds = enabled == true
	self:_remember("Sounds", self.Sounds)
	if not self.Sounds and self.UISound then self.UISound:Stop() end
end

function Window:SetSoundVolume(value)
	self.SoundVolume = math.clamp(tonumber(value) or 0.18, 0, 1)
	self:_remember("SoundVolume", self.SoundVolume)
	if self.UISound then self.UISound.Volume = self.SoundVolume end
end

function Window:SetNotifications(enabled)
	self.NotificationsEnabled = enabled == true
	self:_remember("NotificationsEnabled", self.NotificationsEnabled)
	if not self.NotificationsEnabled then
		for _, frame in ipairs(self.Notifications) do frame:Destroy() end
		table.clear(self.Notifications)
	end
end

function Window:_syncAmbient()
	if self._ambientConnection then self._ambientConnection:Disconnect(); self._ambientConnection = nil end
	if not self.Ambient then return end
	self.Ambient.Visible = self.BackgroundEffects
	if self._destroyed or not self.Visible or not self.BackgroundEffects or not self.BackgroundAnimations or not self.Animations then return end
	local accumulated = 0
	self._ambientConnection = RunService.RenderStepped:Connect(function(delta)
		accumulated += delta
		if accumulated < 1 / 15 then return end
		self._ambientTime = (self._ambientTime or 0) + accumulated
		accumulated = 0
		local t = self._ambientTime
		for index, item in ipairs(self._aurora) do
			item.Gradient.Offset = Vector2.new(math.sin(t * 0.16 + index) * 0.32, 0)
			item.Frame.Rotation = -24 + math.sin(t * 0.11 + index) * 9
			item.Frame.Position = UDim2.fromScale(0.32 + math.sin(t * 0.08 + index) * 0.12, 0.22 + (index - 1) * 0.38)
		end
	end)
end

function Window:SetBackgroundEffects(enabled)
	self.BackgroundEffects = enabled == true
	self:_remember("BackgroundEffects", self.BackgroundEffects)
	self:_syncAmbient()
end

function Window:SetBackgroundAnimations(enabled)
	self.BackgroundAnimations = enabled == true
	self:_remember("BackgroundAnimations", self.BackgroundAnimations)
	self:_syncAmbient()
end

function Window:_initExperience()
	self._aurora, self._coverGradients = {}, {}
	self.Ambient = create("Frame", {
		Name = "AuroraBackground", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
		ClipsDescendants = true, ZIndex = 0, Parent = self.Frame,
	})
	for index = 1, 2 do
		local ribbon = create("Frame", {
		Name = "AuroraRibbon", Position = UDim2.fromScale(0.32, 0.22 + (index - 1) * 0.38),
			Size = UDim2.new(0.95, 0, 0, 210), Rotation = -24,
			BackgroundColor3 = THEME.Accent, BackgroundTransparency = 0.94,
			BorderSizePixel = 0, ZIndex = 0, Parent = self.Ambient,
		}, { corner(100) })
		local gradient = create("UIGradient", {
			Rotation = 90,
			Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0), NumberSequenceKeypoint.new(1, 1) }),
			Parent = ribbon,
		})
		table.insert(self._aurora, { Frame = ribbon, Gradient = gradient })
	end
	self.UISound = create("Sound", {
		Name = "FrostInterfaceSound", SoundId = self.UIState.SoundAsset or UI_DEFAULTS.SoundAsset,
		Volume = self.SoundVolume, Parent = self.Gui,
	})
	self:_syncAmbient()
end

function Window:ApplyPreferences()
	local state = self.UIState or {}
	local accent, success = state.CustomAccent, state.CustomSuccess
	self:SetAnimations(state.Animations ~= false)
	self:SetBackgroundEffects(state.BackgroundEffects == true)
	self:SetBackgroundAnimations(state.BackgroundAnimations == true)
	self:SetSounds(state.Sounds ~= false)
	self:SetSoundVolume(state.SoundVolume or 0.18)
	self:SetNotifications(state.NotificationsEnabled ~= false)
	self:SetTextScale(state.TextScale or 1)
	self:SetDimAmount(state.DimAmount or 40)
	self:SetSizePreset(state.SizePreset or "Large")
	self:SetMonitorWidth(state.MonitorWidth or 380)
	self:SetMonitorSide(state.MonitorSide or "Right")
	self:SetTheme(state.ThemeName or "Black")
	if accent then self:SetThemeColor("Accent", accent) end
	if success then self:SetThemeColor("Success", success) end
	for _, binding in ipairs(self.Keybinds) do binding:Refresh() end
	for _, refresh in ipairs(self._preferenceRefreshers or {}) do refresh() end
end

function Window:AddClientSettings(tab)
	self._preferenceRefreshers = self._preferenceRefreshers or {}
	local function bind(control, key)
		table.insert(self._preferenceRefreshers, function()
			local value = self.UIState[key]
			if value ~= nil then control:SetValue(value, true) end
		end)
		return control
	end
	self:AddThemeGallery(tab)
	local motion = tab:AddModule({ Name = "Motion & atmosphere", Description = "Set the pace of your workspace" })
	bind(motion:AddToggle("Interface animations", self.Animations, function(value) self:SetAnimations(value) end,
		"Turn off all movement for a still interface"), "Animations")
	bind(motion:AddToggle("Decorative background", self.BackgroundEffects, function(value) self:SetBackgroundEffects(value) end,
		"Soft gradients behind your workspace"), "BackgroundEffects")
	bind(motion:AddToggle("Animate background", self.BackgroundAnimations, function(value) self:SetBackgroundAnimations(value) end,
		"Pause ambient movement while keeping the artwork"), "BackgroundAnimations")
	local audio = tab:AddModule({ Name = "Sound & feedback", Description = "Small details, on your terms" })
	bind(audio:AddToggle("Interface sounds", self.Sounds, function(value) self:SetSounds(value) end), "Sounds")
	bind(audio:AddSlider("Sound volume", 0, 1, self.SoundVolume, function(value) self:SetSoundVolume(value) end,
		{ Step = 0.05, Formatter = function(value) return math.floor(value * 100) .. "%" end }), "SoundVolume")
	audio:AddButton("Preview sound", function() self:PlaySound("Open") end)
	bind(audio:AddToggle("Notifications", self.NotificationsEnabled, function(value) self:SetNotifications(value) end), "NotificationsEnabled")
	local appearance = tab:AddModule({ Name = "Appearance", Description = "Color, type, and spacing" })
	appearance:AddColorPicker("Accent", THEME.Accent, function(value) self:SetThemeColor("Accent", value) end)
	bind(appearance:AddDropdown("Window size", { "Comfortable", "Large", "Extra Large" }, self.SizePreset,
		function(value) self:SetSizePreset(value) end), "SizePreset")
	bind(appearance:AddSlider("Text size", 1, 1.3, self.TextScale, function(value) self:SetTextScale(value) end,
		{ Step = 0.05, Formatter = function(value) return string.format("%.2fx", value) end }), "TextScale")
	bind(appearance:AddSlider("Background dim", 0, 75, self.DimAmount, function(value) self:SetDimAmount(value) end,
		{ Step = 5, Formatter = function(value) return value .. "%" end }), "DimAmount")
	local interface = tab:AddModule({ Name = "Window & overlays", Description = "Visibility and monitor placement" })
	interface:AddKeybind({ Name = "Show / hide interface", AllowClear = false, IsVisibility = true,
		Get = function() return Enum.KeyCode[self.UIState.VisibilityKey or "RightShift"] or Enum.KeyCode.RightShift end,
		Set = function(key) self:_remember("VisibilityKey", key.Name) end,
		OnPressed = function() self:Toggle() end })
	bind(interface:AddDropdown("Monitor side", { "Left", "Right" }, self.MonitorSide, function(value) self:SetMonitorSide(value) end), "MonitorSide")
	bind(interface:AddSlider("Monitor width", 320, 520, self.MonitorWidth, function(value) self:SetMonitorWidth(value) end, { Step = 20 }), "MonitorWidth")
	return appearance, motion
end

function Library.ImageContent(image)
	local value = type(image) == "table" and image.AssetId or image
	if value == nil or value == "" then return "" end
	local digits = tostring(value):match("^(%d+)$") or tostring(value):match("^rbxassetid://(%d+)$")
	if not digits or not digits:find("[1-9]") then return "" end
	return "rbxassetid://" .. digits
end

function Tab:AddScriptCard(entry, onLaunch)
	self.ItemNoun = "scripts"
	if not self.CardLayout then
		local list = self.Scroll:FindFirstChildWhichIsA("UIListLayout")
		if list then list:Destroy() end
		self.ScriptCards = {}
		self.CardLayout = create("UIGridLayout", {
			CellSize = UDim2.new(0.5, -10, 0, 300), CellPadding = UDim2.fromOffset(12, 12),
			SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center,
			Parent = self.Scroll,
		})
	end
	local module = self:AddModule({ Name = entry.Name, Description = entry.Description, HeaderHeight = 0, Collapsible = false })
	module.IsScriptCard = true
	-- The grid owns card geometry; cancel the module's initial expansion tween.
	local running = self.Window._tweens[module.Card]
	if running and running.Size then running.Size:Cancel(); running.Size = nil end
	for _, object in ipairs(module.Card:GetChildren()) do
		if object:IsA("GuiObject") then object.Visible = false end
	end
	local cover = create("Frame", { Name = "ScriptCover", ClipsDescendants = true,
		BackgroundColor3 = THEME.AccentSoft, BorderSizePixel = 0, Parent = module.Card }, { corner(10) })
	local gradient = create("UIGradient", { Rotation = 25,
		Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(90, 95, 110)), Parent = cover })
	table.insert(self.Window._coverGradients, gradient)
	local fallback = create("TextLabel", {
		Name = "CoverFallback", Size = UDim2.fromScale(1, 1), Text = entry.Monogram or entry.Name:sub(1, 2):upper(),
		TextSize = 36, Font = Enum.Font.BuilderSansBold, TextColor3 = THEME.Accent,
		BackgroundTransparency = 1, Parent = cover,
	})
	local cardHovered = false
	local image = create("ImageLabel", {
		Name = "CustomCover", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
		Image = Library.ImageContent(entry.Image),
		ScaleType = type(entry.Image) == "table" and entry.Image.ScaleType == "Fit" and Enum.ScaleType.Fit or Enum.ScaleType.Crop,
		ZIndex = 2, Parent = cover,
	}, { corner(10) })
	image.Visible = image.Image ~= ""
	local hoverWash = create("Frame", {
		Name = "CardHoverWash", Size = UDim2.fromScale(1, 1), BackgroundColor3 = THEME.Accent,
		BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 3, Parent = cover,
	}, { corner(10) })
	local hoverHint = create("TextLabel", {
		Name = "CardHoverHint", AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -10),
		Size = UDim2.new(1, -20, 0, 18), BackgroundTransparency = 1, Text = "OPEN WORKSPACE",
		TextColor3 = THEME.Text, TextTransparency = 1, Font = Enum.Font.BuilderSansBold, TextSize = 10,
		Parent = cover, ZIndex = 4,
	})
	local function imageReady() fallback.Visible = not cardHovered and not (image.Visible and image.IsLoaded) end
	self.Window:_connect(image:GetPropertyChangedSignal("IsLoaded"), imageReady)
	imageReady()
	if self.Window.ResolveCover then
		task.spawn(function()
			local ok, content = pcall(self.Window.ResolveCover, entry)
			if ok and content and not self.Window._destroyed then
				image.Image, image.Visible = content, true
				imageReady()
			end
		end)
	end
	local function label(name, text, size, color, font)
		return create("TextLabel", { Name = name, Text = text, TextSize = size, Font = font,
			TextColor3 = color, TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top, BackgroundTransparency = 1, Parent = module.Card })
	end
	local title = label("ScriptTitle", entry.Name, 17, THEME.Text, Enum.Font.BuilderSansBold)
	local description = label("ScriptDescription", entry.Description, 13, THEME.Muted, Enum.Font.BuilderSans)
	description.TextWrapped = true
	local status = label("LaunchStatus", "Open in the matching game", 11, THEME.Muted, Enum.Font.BuilderSans)
	local button = create("TextButton", { Name = "LaunchScript", Text = "Launch script",
		TextSize = 14, Font = Enum.Font.BuilderSansMedium, TextColor3 = THEME.Text,
		BackgroundColor3 = THEME.Surface, BorderSizePixel = 0, AutoButtonColor = false, Parent = module.Card,
	}, { corner(8), stroke(THEME.Accent, 0.65) })
	self.Window:_hover(button, THEME.Surface, THEME.SurfaceHover)
	local cardStroke = module.Card:FindFirstChildWhichIsA("UIStroke")
	local function setHovered(hovered)
		cardHovered = hovered
		imageReady()
		self.Window:_tween(module.Card, 0.13, { BackgroundColor3 = hovered and THEME.Surface or THEME.PanelRaised })
		if cardStroke then self.Window:_tween(cardStroke, 0.13, { Color = hovered and THEME.Accent or THEME.Border, Transparency = hovered and 0.3 or 0.25 }) end
		self.Window:_tween(hoverWash, 0.13, { BackgroundTransparency = hovered and 0.84 or 1 })
		self.Window:_tween(hoverHint, 0.13, { TextTransparency = hovered and hoverHint.Visible and 0 or 1 })
		if hovered then self.Window:PlaySound("Hover") end
	end
	self.Window:_connect(module.Card.MouseEnter, function() setHovered(true) end)
	self.Window:_connect(module.Card.MouseLeave, function() setHovered(false) end)
	self.Window:_connect(button.Activated, function() if button.Active then safeCall(self.Window, onLaunch) end end)
	local card = { Module = module, Button = button, Cover = cover, Image = image, Title = title, Description = description, Status = status }
	function card:Layout(horizontal, height)
		local textScale = self.Module.Window.TextScale
		local titleHeight = math.ceil(24 * textScale)
		if horizontal then
			local compact = height < 100
			local side = math.min(104, height - (compact and 20 or 24))
			local left = side + 26
			cover.Position, cover.Size = UDim2.fromOffset(compact and 10 or 12, compact and 10 or 12), UDim2.fromOffset(side, side)
			local compactTitleHeight = compact and math.min(20, titleHeight) or titleHeight
			title.Position, title.Size = UDim2.fromOffset(left, compact and 6 or 10), UDim2.new(1, -left - 12, 0, compactTitleHeight)
			local descriptionTop = (compact and 8 or 14) + compactTitleHeight
			local buttonHeight = compact and 28 or 32
			local buttonBottom = compact and 6 or 8
			local buttonY = height - buttonHeight - buttonBottom
			description.Position, description.Size = UDim2.fromOffset(left, descriptionTop), UDim2.new(1, -left - 12, 0, math.max(12, buttonY - descriptionTop - 4))
			button.Position, button.Size = UDim2.fromOffset(left, buttonY), UDim2.new(1, -left - 12, 0, buttonHeight)
			hoverHint.Visible = side >= 84
			status.Visible = false
		else
			local descriptionHeight = math.ceil(52 * textScale)
			local coverHeight = height - 116 - titleHeight - descriptionHeight
			cover.Position, cover.Size = UDim2.fromOffset(12, 12), UDim2.new(1, -24, 0, coverHeight)
			title.Position, title.Size = UDim2.fromOffset(14, coverHeight + 24), UDim2.new(1, -28, 0, titleHeight)
			description.Position, description.Size = UDim2.fromOffset(14, coverHeight + 31 + titleHeight), UDim2.new(1, -28, 0, descriptionHeight)
			button.Position, button.Size = UDim2.new(0, 12, 1, -68), UDim2.new(1, -24, 0, 38)
			status.Position, status.Size = UDim2.new(0, 14, 1, -23), UDim2.new(1, -28, 0, 16)
			hoverHint.Visible = coverHeight >= 84
			status.Visible = true
		end
	end
	function card:SetLaunchState(state, detail)
		self.Button.Text = state == "Loading" and "Loading..." or state == "Retry" and "Try again" or "Launch script"
		status.Text = detail or "Open in the matching game"
	end
	function card:SetLaunchEnabled(enabled)
		self.Button.Active, self.Button.Selectable = enabled, enabled
		self.Button.TextTransparency = enabled and 0 or 0.4
	end
	card:SetLaunchEnabled(true)
	table.insert(self.ScriptCards, card)
	self.Window:_layoutScriptCards()
	return card
end

-- Composed with Library.lua by the build; shares its private UI helpers.
function Window:_targetWindowSize()
	local viewport = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
	local scale = math.min(1, math.max(1, viewport.X - 24) / 460, math.max(1, viewport.Y - 24) / 420)
	local preset = SIZE_PRESETS[self.SizePreset] or SIZE_PRESETS.Large
	self.Scale.Scale = scale
	return Vector2.new(math.clamp((viewport.X - 24) / scale, 460, preset.X),
		math.clamp((viewport.Y - 24) / scale, 420, preset.Y))
end

function Window:_resizeWindow(animate)
	if self._destroyed then return end
	self:CloseDropdown()
	self.TargetSize = self:_targetWindowSize()
	local compact = self.TargetSize.X < 800
	local sidebarWidth = compact and 68 or 192
	self.Sidebar.Size = UDim2.new(0, sidebarWidth, 1, 0)
	self.Main.Position = UDim2.fromOffset(sidebarWidth, 0)
	self.Main.Size = UDim2.new(1, -sidebarWidth, 1, 0)
	self.BrandName.Visible = not compact
	self.BrandSubtitle.Visible = not compact
	self.NavCaption.Visible = not compact
	self.PlayerName.Visible = not compact
	self.Avatar.Position = UDim2.fromOffset(compact and 3 or 10, 10)
	self.Logo.Position = UDim2.fromOffset(compact and 14 or 20, 24)
	for _, tab in ipairs(self.Tabs) do
		tab.Label.Visible = not compact
		tab.IconLabel.Position = UDim2.fromOffset(compact and 8 or 13, 12)
	end
	self._compact = compact
	self:_layoutScriptCards()
	self:_layoutDashboardCards()
	for _, gallery in ipairs(self.ThemeGalleries or {}) do gallery:Layout() end
	local size = UDim2.fromOffset(self.TargetSize.X, self.TargetSize.Y)
	if animate then self:_tween(self.Frame, 0.2, { Size = size }) else self.Frame.Size = size end
	self.Frame.Position = UDim2.fromScale(0.5, 0.5)
	self:_layoutMonitors()
	self:_layoutNotifications()
end

function Window:_layoutDashboardCards()
	if not self.TargetSize then return end
	local availableWidth = self.TargetSize.X - (self._compact and 68 or 192) - 40
	local columns = availableWidth >= 590 and 2 or 1
	for _, tab in ipairs(self.Tabs) do
		if tab.DashboardGrid then
			tab.DashboardGrid.CellSize = UDim2.new(1 / columns, columns == 2 and -10 or -8, 0, 174)
		end
	end
end

function Window:_layoutScriptCards()
	if not self.TargetSize then return end
	local availableWidth = self.TargetSize.X - (self._compact and 68 or 192) - 40
	local availableHeight = self.TargetSize.Y - 186
	local horizontal = availableWidth < 520 or availableHeight < 250
	local columns = horizontal and 1 or 2
	for _, tab in ipairs(self.Tabs) do
		if tab.CardLayout then
			local count = math.min(2, math.max(1, #tab.ScriptCards))
			local height = horizontal and math.clamp(math.floor((availableHeight - 8 - (count - 1) * 12) / count), 78, 152)
				or math.min(244 + math.ceil((self.TextScale - 1) * 72), availableHeight - 8)
			tab.CardLayout.CellSize = UDim2.new(1 / columns, columns == 2 and -10 or -8, 0, height)
			for _, card in ipairs(tab.ScriptCards) do card:Layout(horizontal, height) end
		end
	end
end

function Window:_refreshSearch()
	if self._destroyed or not self.ActiveTab then return end
	local tab = self.ActiveTab
	local query = (self.Search.Text or ""):lower()
	local shown, active = 0, 0
	for _, module in ipairs(tab.Modules) do
		local matches = not self.ActiveOnly or module.Enabled
		for word in query:gmatch("%S+") do
			if not module.SearchText:find(word, 1, true) then matches = false; break end
		end
		module.Card.Visible = matches
		if matches then shown += 1 end
		if module.Enabled then active += 1 end
	end
	self.Empty.Visible = shown == 0
	self.Empty.Text = #tab.Modules == 0 and "Your workspace is ready.\nAdd a module to get started."
		or "No matching modules\nTry a different search or turn off Active."
	self.Footer.Text = tab.ItemNoun == "scripts" and string.format("%d scripts in your collection", shown)
		or string.format("%d of %d modules  ·  %d active", shown, #tab.Modules, active)
end

function Window:SetSearch(query)
	self.Search.Text = tostring(query or "")
	self:_refreshSearch()
end

function Window:SetActiveOnly(enabled)
	self.ActiveOnly = enabled == true
	self:_tween(self.ActiveFilter, 0.12, {
		BackgroundColor3 = self.ActiveOnly and THEME.AccentSoft or THEME.PanelRaised,
		TextColor3 = self.ActiveOnly and THEME.Accent or THEME.Muted,
	})
	self:_refreshSearch()
end

function Window:CloseDropdown()
	if not self._dropdown then return end
	for _, connection in ipairs(self._dropdown.Connections) do connection:Disconnect() end
	self._dropdown.Root:Destroy()
	self._dropdown = nil
end

function Window:_openDropdown(control, name, options, anchor)
	if self._dropdown and self._dropdown.Control == control then self:CloseDropdown(); return end
	self:CloseDropdown()
	local root = create("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 20, Parent = self.Gui })
	local connections = {}
	local function connect(signal, callback) table.insert(connections, signal:Connect(callback)) end
	self._dropdown = { Root = root, Control = control, Connections = connections }
	local scrim = create("TextButton", {
		Size = UDim2.fromScale(1, 1), Text = "", AutoButtonColor = false,
		BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, ZIndex = 20, Parent = root,
	})
	connect(scrim.Activated, function() self:CloseDropdown() end)
	local viewport = self.Gui.AbsoluteSize
	local width = math.min(360, math.max(180, viewport.X - 32))
	local height = math.min(360, math.max(140, viewport.Y - 32))
	local x = math.clamp(anchor.AbsolutePosition.X, 16, math.max(16, viewport.X - width - 16))
	local y = math.clamp(anchor.AbsolutePosition.Y, 16, math.max(16, viewport.Y - height - 16))
	local panel = create("Frame", {
		Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(width, height),
		BackgroundColor3 = THEME.Panel, BorderSizePixel = 0, ZIndex = 21, Parent = root,
	}, { corner(14), stroke(THEME.Border, 0) })
	create("TextLabel", {
		Position = UDim2.fromOffset(16, 8), Size = UDim2.new(1, -70, 0, 32), Text = name,
		BackgroundTransparency = 1, TextColor3 = THEME.Text, Font = Enum.Font.BuilderSansBold,
		TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 22, Parent = panel,
	})
	local close = create("TextButton", {
		Position = UDim2.new(1, -48, 0, 0), Size = UDim2.fromOffset(44, 44), Text = "×",
		BackgroundTransparency = 1, TextColor3 = THEME.Muted, TextSize = 22, Font = Enum.Font.BuilderSans,
		ZIndex = 22, Parent = panel,
	})
	connect(close.Activated, function() self:CloseDropdown() end)
	local filter = create("TextBox", {
		Position = UDim2.fromOffset(12, 46), Size = UDim2.new(1, -24, 0, 40), Text = "",
		PlaceholderText = "Find an option…", ClearTextOnFocus = false,
		BackgroundColor3 = THEME.Surface, BorderSizePixel = 0, TextColor3 = THEME.Text,
		PlaceholderColor3 = THEME.Muted, TextSize = 13, Font = Enum.Font.BuilderSans,
		ZIndex = 22, Parent = panel,
	}, { corner(8) })
	local list = create("ScrollingFrame", {
		Position = UDim2.fromOffset(12, 94), Size = UDim2.new(1, -24, 1, -106),
		AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(),
		BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3,
		ScrollBarImageColor3 = THEME.Accent, ZIndex = 22, Parent = panel,
	}, { create("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }) })
	local entries = {}
	for index, option in ipairs(options) do
		local label, value = optionParts(option)
		label = self:Text(label)
		local selected = value == control.Value
		local button = create("TextButton", {
			Size = UDim2.new(1, -5, 0, 44), LayoutOrder = index,
			Text = (selected and "✓  " or "    ") .. label,
			TextColor3 = selected and THEME.Accent or THEME.Text, Font = Enum.Font.BuilderSansMedium,
			TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundColor3 = selected and THEME.AccentSoft or THEME.PanelRaised,
			BorderSizePixel = 0, AutoButtonColor = true, ZIndex = 23, Parent = list,
		}, { corner(8) })
		table.insert(entries, { Label = label:lower(), Button = button })
		connect(button.Activated, function() self:CloseDropdown(); control:SetValue(value) end)
	end
	connect(filter:GetPropertyChangedSignal("Text"), function()
		for _, entry in ipairs(entries) do entry.Button.Visible = entry.Label:find(filter.Text:lower(), 1, true) ~= nil end
	end)
end

function Library:CreateWindow(options)
	options = table.clone(options or {})
	translate = makeText(options.TextData or UI_COPY, options.TextScope or "Shared")
	local state = options.UIState or {}
	for key, value in pairs(UI_DEFAULTS) do
		if state[key] == nil then state[key] = options[key] == nil and value or options[key] end
	end
	for key, value in pairs(state) do options[key] = value end
	options.Theme = state.ThemeName or options.Theme
	local player = Players.LocalPlayer
	local parent = player:WaitForChild("PlayerGui")
	pcall(function() if type(gethui) == "function" then parent = gethui() end end)
	local guiName = options.GuiName or "FrostScriptsUI"
	if self._windows and self._windows[guiName] then self._windows[guiName]:Destroy() end
	self._windows = self._windows or {}
	local overlayName = options.OverlayName or "FrostScriptsOverlays"
	for _, name in ipairs({ guiName, overlayName, overlayName .. "Notifications" }) do
		local existing = parent:FindFirstChild(name)
		if existing then existing:Destroy() end
	end
	local window = setmetatable({
		UIState = state, InputEnabled = true, ResolveCover = options.ResolveCover, Translate = translate,
		Animations = options.Animations ~= false, Visible = true,
		BackgroundEffects = options.BackgroundEffects ~= false,
		BackgroundAnimations = options.BackgroundAnimations ~= false,
		Sounds = options.Sounds ~= false, SoundVolume = math.clamp(tonumber(options.SoundVolume) or 0.18, 0, 1),
		NotificationsEnabled = options.NotificationsEnabled ~= false,
		SizePreset = options.SizePreset or "Large", ThemeName = options.Theme or "Black",
		TextScale = math.clamp(tonumber(options.TextScale) or 1, 1, 1.3),
		DimAmount = math.clamp(tonumber(options.DimAmount) or 40, 0, 75),
		MonitorWidth = math.clamp(tonumber(options.MonitorWidth) or 380, 320, 520),
		MonitorSide = options.MonitorSide == "Left" and "Left" or "Right",
		Tabs = {}, _tabsByName = {}, Keybinds = {}, Monitors = {}, Notifications = {},
		_monitorCount = 0, _connections = {}, _tweens = setmetatable({}, { __mode = "k" }),
		ActiveOnly = false, _visibilityToken = 0,
		ReservedKeys = options.ReservedKeys or {
			[Enum.KeyCode.W] = true, [Enum.KeyCode.A] = true, [Enum.KeyCode.S] = true,
			[Enum.KeyCode.D] = true, [Enum.KeyCode.Space] = true, [Enum.KeyCode.LeftControl] = true,
		},
	}, Window)
	self._windows[guiName] = window
	window.Gui = create("ScreenGui", {
		Name = guiName, ResetOnSpawn = false, IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 100, Parent = parent,
	})
	window.OverlayGui = create("ScreenGui", {
		Name = overlayName, ResetOnSpawn = false, IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 90, Parent = parent,
	})
	window.NotificationGui = create("ScreenGui", {
		Name = overlayName .. "Notifications", ResetOnSpawn = false, IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 102, Parent = parent,
	})
	window.Shade = create("Frame", {
		Name = "Shade", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 1 - window.DimAmount / 100, BorderSizePixel = 0, Parent = window.Gui,
	})
	window.Frame = create("Frame", {
		Name = "FrostWorkspace", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(880, 540), BackgroundColor3 = THEME.Background,
		BorderSizePixel = 0, ClipsDescendants = true, Parent = window.Gui,
